43: // Helper function to convert Uint8Array to base64
44: function uint8ArrayToBase64(uint8Array: Uint8Array): string {
45:   const chunkSize = 0x8000; // 32KB chunks to avoid stack overflow
46:   let binary = "";
47: 
48:   for (let i = 0; i < uint8Array.length; i += chunkSize) {
49:     const chunk = uint8Array.subarray(i, i + chunkSize);
50:     binary += String.fromCharCode(...chunk);
51:   }
52: 
53:   return btoa(binary);
54: }
